#include "api_diagnostics.hpp"
#include <algorithm>
#include <mutex>
#include <unordered_map>
namespace scratchbird::engine::internal_api {namespace{std::mutex m;std::unordered_map<std::string,scratchbird::engine::sblr::SblrInsertDescriptorV1> live,used;uint64_t gen=0;std::string key(const auto&a){static constexpr char h[]="0123456789abcdef";std::string s;for(auto b:a){s+=h[b>>4];s+=h[b&15];}return s;}bool tag(const EngineRequestContext&c,const char*t){return c.security_context_present&&std::find(c.trace_tags.begin(),c.trace_tags.end(),t)!=c.trace_tags.end();}EngineApiDiagnostic d(std::string c,std::string k){return MakeEngineApiDiagnostic(std::move(c),std::move(k),{});}}
SblrInsertCoordinationResult CompileSblrInsertDescriptor(const EngineRequestContext&c,const std::string&r,uint64_t occurrence,uint32_t insert_occurrence,uint64_t availability){std::lock_guard l(m);SblrInsertCoordinationResult x;if(!tag(c,"private_insert_compiler")||!c.statement_metadata_snapshot_engine_owned){x.diagnostic=d("SECURITY.ACCESS_DENIED","sblr.insert.hidden");return x;}if(r!=c.statement_uuid.canonical||!occurrence||!insert_occurrence||!availability){x.diagnostic=d("SBLR.OPERAND_INVALID","sblr.insert.coordination_invalid");return x;}auto&v=x.descriptor;v.canonical_body[0]=1;for(size_t i=1;i<16;i++)v.canonical_body[i]=static_cast<uint8_t>((occurrence>>(i%8))+i);for(size_t i=16;i<32;i++)v.canonical_body[i]=static_cast<uint8_t>((insert_occurrence+i)&255);v.canonical_body[32]=1;v.canonical_body[33]=1;v.availability_generation=availability;auto b=scratchbird::engine::sblr::EncodeSblrInsertDescriptorV1(v,false);if(b.empty()||!scratchbird::engine::sblr::DecodeSblrInsertDescriptorV1(b.data(),b.size(),&v,nullptr,false)){x.diagnostic=d("DML.INSERT_FAILED","sblr.insert.publish_failed");return x;}live[key(v.evidence)]=v;x.ok=true;x.diagnostic=d("OK","ok");return x;}
SblrInsertCoordinationResult ConsumeSblrInsertDescriptor(const EngineRequestContext&c,const scratchbird::engine::sblr::SblrInsertDescriptorV1&v){std::lock_guard l(m);SblrInsertCoordinationResult x;if(!tag(c,"private_insert")){x.diagnostic=d("SECURITY.ACCESS_DENIED","sblr.insert.hidden");return x;}auto k=key(v.evidence);auto it=live.find(k);if(it==live.end()){x.diagnostic=used.count(k)?d("MGA.TRANSACTION.STALE","sblr.insert.stale"):d("SECURITY.ACCESS_DENIED","sblr.insert.hidden");return x;}if(c.query_cancellation_requested&&c.query_cancellation_requested()){x.diagnostic=d("PROCESS.CANCELLED","sblr.insert.cancelled");return x;}used[k]=v;live.erase(it);x.ok=true;x.descriptor=v;x.diagnostic=d("OK","ok");return x;}}
